    "source": "// 0-1 knapsack greedy-by-density (NOT optimal) — complete C++17 reference.\n#include <algorithm>\n#include <numeric>\n#include <utility>\n#include <vector>\n\nstd::pair<long long, std::vector<int>> knapsackGreedyByDensity(const std::vector<int>& weights, const std::vector<long long>& values, int W) {\n    std::vector<int> order(weights.size());\n    std::iota(order.begin(), order.end(), 0);\n    std::stable_sort(order.begin(), order.end(), [&](int a, int b) { return 1.0 * values[a] / weights[a] > 1.0 * values[b] / weights[b]; });\n    int rem = W;\n    long long value = 0;\n    std::vector<int> selected;\n    for (int i : order) {\n        if (weights[i] <= rem) {\n            rem -= weights[i];\n            value += values[i];\n            selected.push_back(i);\n        }\n    }\n    return {value, selected};\n}\n",
