    "source": "/// 0-1 knapsack greedy-by-density (NOT optimal) — complete Rust reference (capacity W is `cap`).\npub fn knapsack_greedy_by_density(weights: &[usize], values: &[i64], cap: usize) -> (i64, Vec<usize>) {\n    let density = |i: usize| values[i] as f64 / weights[i] as f64;\n    let mut order: Vec<usize> = (0..weights.len()).collect();\n    order.sort_by(|&a, &b| density(b).total_cmp(&density(a)));\n    let mut rem = cap;\n    let mut value = 0;\n    let mut selected: Vec<usize> = Vec::new();\n    for i in order {\n        if weights[i] <= rem {\n            rem -= weights[i];\n            value += values[i];\n            selected.push(i);\n        }\n    }\n    (value, selected)\n}\n",
